import React, { useState } from 'react';
import { Sparkles, MessageSquare, Loader2, HardHat, Tractor, Mountain, Calendar } from 'lucide-react';
import { geminiService } from '../services/geminiService';
import { AdvisorSuggestion } from '../types';

const ProjectAdvisor: React.FC = () => {
  const [description, setDescription] = useState('');
  const [loading, setLoading] = useState(false);
  const [suggestion, setSuggestion] = useState<AdvisorSuggestion | null>(null);

  const handleConsult = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!description.trim()) return;

    setLoading(true);
    try {
      const result = await geminiService.getProjectAdvice(description);
      setSuggestion(result);
    } catch (err) {
      alert("Consultation failed. Please check your API configuration.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-slate-50 min-h-screen py-12">
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center mb-12">
          <div className="inline-flex items-center justify-center p-3 bg-orange-100 rounded-2xl mb-6">
            <Sparkles className="text-orange-600 w-8 h-8" />
          </div>
          <h1 className="text-4xl font-extrabold text-slate-900 mb-4">Gemini AI Project Advisor</h1>
          <p className="text-slate-600 text-lg">Describe your project and let our AI suggest the right experts, tools, and land requirements.</p>
        </div>

        <div className="bg-white rounded-[32px] p-8 shadow-sm border border-slate-200 mb-12">
          <form onSubmit={handleConsult}>
            <label className="block text-sm font-bold text-slate-700 mb-4 uppercase tracking-widest">Your Project Description</label>
            <textarea 
              className="w-full h-40 p-6 bg-slate-50 rounded-2xl border border-slate-200 focus:ring-2 focus:ring-orange-500 outline-none transition-all resize-none text-slate-700 mb-6"
              placeholder="e.g., I'm planning to build a small 2-story sustainable family home with a backyard pool on a 1-acre plot..."
              value={description}
              onChange={(e) => setDescription(e.target.value)}
            />
            <button 
              type="submit"
              disabled={loading || !description}
              className="w-full bg-orange-600 hover:bg-orange-700 disabled:bg-slate-300 text-white py-5 rounded-2xl font-bold flex items-center justify-center transition-all text-lg"
            >
              {loading ? (
                <>
                  <Loader2 className="animate-spin mr-3 w-6 h-6" /> Analyzing Requirements...
                </>
              ) : (
                <>
                  Generate AI Roadmap <Sparkles className="ml-2 w-5 h-5" />
                </>
              )}
            </button>
          </form>
        </div>

        {suggestion && (
          <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
            <h2 className="text-2xl font-bold text-slate-900 flex items-center">
              <MessageSquare className="mr-3 text-orange-600" /> AI Suggestions
            </h2>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
                <div className="flex items-center text-orange-600 font-bold mb-4">
                  <HardHat className="mr-2 w-5 h-5" /> Recommended Talent
                </div>
                <ul className="space-y-2">
                  {suggestion.neededEngineers.map((role, i) => (
                    <li key={i} className="text-slate-600 flex items-center">
                      <div className="w-1.5 h-1.5 bg-orange-600 rounded-full mr-3"></div>
                      {role}
                    </li>
                  ))}
                </ul>
              </div>

              <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
                <div className="flex items-center text-blue-600 font-bold mb-4">
                  <Tractor className="mr-2 w-5 h-5" /> Essential Equipment
                </div>
                <ul className="space-y-2">
                  {suggestion.suggestedEquipment.map((eq, i) => (
                    <li key={i} className="text-slate-600 flex items-center">
                      <div className="w-1.5 h-1.5 bg-blue-600 rounded-full mr-3"></div>
                      {eq}
                    </li>
                  ))}
                </ul>
              </div>

              <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm md:col-span-2">
                <div className="flex items-center text-green-600 font-bold mb-4">
                  <Mountain className="mr-2 w-5 h-5" /> Land Acquisition Advice
                </div>
                <p className="text-slate-600 leading-relaxed italic border-l-4 border-green-100 pl-4">
                  "{suggestion.landAdvice}"
                </p>
              </div>

              <div className="bg-slate-900 p-8 rounded-3xl border border-slate-800 shadow-sm md:col-span-2 text-white">
                <div className="flex items-center text-orange-400 font-bold mb-4">
                  <Calendar className="mr-2 w-5 h-5" /> Estimated Timeline
                </div>
                <p className="text-slate-300 leading-relaxed">
                  {suggestion.estimatedTimeline}
                </p>
              </div>
            </div>

            <div className="flex justify-center pt-8">
              <button 
                onClick={() => setSuggestion(null)}
                className="text-slate-500 hover:text-slate-900 font-medium transition-colors"
              >
                Start new consultation
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default ProjectAdvisor;

