import React, { useState, useMemo } from 'react';
import { Map, Marker, ZoomControl } from 'pigeon-maps';
import { Coordinates } from '../types';
import { MapPin, X, ArrowRight, Layers } from 'lucide-react';

interface MapItem {
  id: string;
  title: string;
  subtitle: string;
  coordinates: Coordinates;
  image?: string;
  price?: string;
}

interface MapViewProps {
  items: MapItem[];
  center?: [number, number];
  zoom?: number;
  onActionClick?: (id: string) => void;
  actionLabel?: string;
}

interface Cluster {
  id: string;
  items: MapItem[];
  center: [number, number];
  isCluster: boolean;
}

const MapView: React.FC<MapViewProps> = ({ 
  items, 
  center: initialCenter = [37.0902, -95.7129], 
  zoom: initialZoom = 4,
  onActionClick,
  actionLabel = "View Details"
}) => {
  const [selectedItem, setSelectedItem] = useState<MapItem | null>(null);
  const [zoom, setZoom] = useState(initialZoom);
  const [center, setCenter] = useState<[number, number]>(initialCenter);

  // Simple distance-based clustering algorithm
  const clusters = useMemo(() => {
    if (zoom >= 12) {
      // At high zoom, just show individual items as single-item "clusters"
      return items.map(item => ({
        id: item.id,
        items: [item],
        center: [item.coordinates.lat, item.coordinates.lng] as [number, number],
        isCluster: false
      }));
    }

    const result: Cluster[] = [];
    const processed = new Set<string>();

    // Clustering radius in degrees, scales with zoom
    // At zoom 4, ~2 degrees is a good cluster radius
    const radius = 5 / Math.pow(1.8, zoom - 2);

    for (const item of items) {
      if (processed.has(item.id)) continue;

      const clusterItems = [item];
      processed.add(item.id);

      for (const other of items) {
        if (processed.has(other.id)) continue;

        const distance = Math.sqrt(
          Math.pow(item.coordinates.lat - other.coordinates.lat, 2) +
          Math.pow(item.coordinates.lng - other.coordinates.lng, 2)
        );

        if (distance < radius) {
          clusterItems.push(other);
          processed.add(other.id);
        }
      }

      // Calculate centroid
      const latSum = clusterItems.reduce((sum, i) => sum + i.coordinates.lat, 0);
      const lngSum = clusterItems.reduce((sum, i) => sum + i.coordinates.lng, 0);

      result.push({
        id: `cluster-${item.id}`,
        items: clusterItems,
        center: [latSum / clusterItems.length, lngSum / clusterItems.length],
        isCluster: clusterItems.length > 1
      });
    }

    return result;
  }, [items, zoom]);

  const handleMarkerClick = (cluster: Cluster) => {
    if (cluster.isCluster) {
      // Zoom into the cluster
      setCenter(cluster.center);
      setZoom(Math.min(zoom + 2, 18));
      setSelectedItem(null);
    } else {
      // Select the individual item
      const item = cluster.items[0];
      setSelectedItem(item);
      setCenter([item.coordinates.lat, item.coordinates.lng]);
    }
  };

  return (
    <div className="relative w-full h-[600px] rounded-[32px] overflow-hidden border border-slate-200 shadow-inner bg-slate-100">
      <Map 
        height={600} 
        center={center}
        zoom={zoom}
        onBoundsChanged={({ center, zoom }) => {
          setCenter(center);
          setZoom(zoom);
        }}
        metaWheelZoom={true}
      >
        <ZoomControl />
        {clusters.map((cluster) => (
          <Marker 
            key={cluster.id} 
            anchor={cluster.center} 
            onClick={() => handleMarkerClick(cluster)}
          >
            {cluster.isCluster ? (
              // Custom Cluster Marker
              <div className="relative group cursor-pointer">
                <div className="absolute -inset-2 bg-orange-500/20 rounded-full animate-pulse group-hover:bg-orange-500/30 transition-all"></div>
                <div className="w-10 h-10 bg-gradient-to-br from-orange-500 to-orange-600 rounded-full border-2 border-white shadow-lg flex items-center justify-center text-white text-xs font-black transition-transform group-hover:scale-110">
                  {cluster.items.length}
                </div>
              </div>
            ) : (
              // Standard Marker
              <div className={`w-6 h-6 rounded-full border-2 border-white shadow-md flex items-center justify-center transition-all ${
                selectedItem?.id === cluster.items[0].id ? 'bg-orange-600 scale-125' : 'bg-slate-700 hover:bg-slate-800'
              }`}>
                <div className="w-2 h-2 bg-white rounded-full"></div>
              </div>
            )}
          </Marker>
        ))}
      </Map>

      {/* Item Detail Popup */}
      {selectedItem && (
        <div className="absolute bottom-6 left-6 right-6 md:left-auto md:w-80 bg-white rounded-2xl shadow-2xl p-4 border border-slate-100 animate-in fade-in slide-in-from-bottom-2 duration-300 z-10">
          <button 
            onClick={() => setSelectedItem(null)}
            className="absolute top-2 right-2 p-1 hover:bg-slate-100 rounded-full text-slate-400 transition-colors"
          >
            <X className="w-4 h-4" />
          </button>

          <div className="flex gap-4 mb-4">
            {selectedItem.image && (
              <img 
                src={selectedItem.image} 
                alt={selectedItem.title} 
                className="w-16 h-16 rounded-xl object-cover shrink-0" 
              />
            )}
            <div className="flex-1 min-w-0">
              <h4 className="font-bold text-slate-900 truncate">{selectedItem.title}</h4>
              <p className="text-xs text-slate-500 truncate flex items-center">
                <MapPin className="w-3 h-3 mr-1" /> {selectedItem.subtitle}
              </p>
              {selectedItem.price && (
                <div className="text-orange-600 font-bold text-sm mt-1">
                  {selectedItem.price}
                </div>
              )}
            </div>
          </div>

          {onActionClick && (
            <button 
              onClick={() => onActionClick(selectedItem.id)}
              className="w-full bg-slate-900 text-white py-2 rounded-xl text-sm font-bold flex items-center justify-center hover:bg-slate-800 transition-colors"
            >
              {actionLabel} <ArrowRight className="w-4 h-4 ml-2" />
            </button>
          )}
        </div>
      )}

      {/* Cluster Legend */}
      <div className="absolute top-4 left-4 bg-white/90 backdrop-blur px-3 py-1.5 rounded-full text-[10px] font-bold text-slate-600 shadow-sm border border-slate-200 flex items-center gap-2 pointer-events-none uppercase tracking-wider">
        <Layers className="w-3 h-3 text-orange-500" /> Clustering Active
      </div>

      <div className="absolute top-4 right-4 bg-white/90 backdrop-blur px-3 py-1.5 rounded-full text-[10px] font-bold text-slate-500 shadow-sm border border-slate-200 pointer-events-none uppercase tracking-wider">
        {items.length} Engineers found
      </div>
    </div>
  );
};

export default MapView;

